INSERT OR REPLACE INTO books (name, registered, status, horizon, universe, direction, entry, stop, exit_rule, kill_criterion, doc, notes) VALUES ('Golden-cross long v1', '2026-10-19', 'running', '4h bars, 18-bar (3-day) hold', '27 registered coins', 'long', 'CONFIRMED 20/50 golden cross: within 20 bars of the cross, EMA20 > 0.5 ATR14 above EMA50 and close above EMA20; only while BTC is above its 4h EMA200; long at the close, 4.5bp', '3 x ATR14(entry) below entry, worst tick', 'hold 18 bars then close; 4.5bp out', 'min 120 closed or 6 months; PASS mean>0 net AND beats the time-matched random shadow long; early kill any 25-trade block < -3%', '83', 'finding 152: +1.49%/ep t=5.2 vs +0.21% random, 78% coins, split-half +0.8/+1.1; fat-tailed (top 5% of trades > all profit). Kill switch flatten=1 OR 2 closes and blocks it (it is a long). src/paperbook5.py, runs/paper5_state.json');
INSERT OR REPLACE INTO findings (doc, title, date, verdict, summary) VALUES ('152', 'Confirmed golden cross on 4h, held (doc 83)', '2026-10-19', 'PROMISING', 'Tightening the golden cross: the cross itself is not the entry; wait (<=20 bars) for the ribbon to open >0.5 ATR with close above EMA20, then HOLD 12-24 bars with no trailing stop. Hold 12: +0.93%/ep t=4.4 vs +0.03% random (5 controls/trade), 70% coins, 4/6 years, split-half +0.79/+1.07, race 54% vs 48%. With BTC>EMA200 gate, hold 18: +1.49% t=5.2, 78% coins. 3-ATR safety stop keeps +0.77% t=3.7. Fat tails: worst -22.6%, top 5% = 127% of P&L. Rejected gates: pullback on 4h (-0.36%), week4, not-US. Daily bars: bull+first-pullback+hold 10 +5.2% t=4.3 (n=203, 2025 negative) - noted, not registered.');
INSERT OR REPLACE INTO rules (id, rule, why, doc, added) VALUES (163, 'A trend entry on crypto is held, not trailed: the 20/50 golden cross made money only with a fixed hold (no stop or a 3-ATR safety stop); every trailing or tight-stop exit gave the move back. Mirror of doc 80 for the short side, where the trail wins.', 'golden_verify.py: hold 12 +0.93% vs scaled +0.20% vs trail -0.86%', '83', '2026-10-19');
